from eth_abi import encode as abi_encode
from eth_utils import keccak, to_canonical_address, to_checksum_address
import rlp

from eth_rescue.types import PreparedAction

RESCUE_SELECTOR = bytes.fromhex("789ffa0e")

# Compiled from contracts/src/EthRescue.sol (solc 0.8.31, optimizer runs 6900).
ETH_RESCUE_CREATION_BYTECODE = bytes.fromhex(
    ""  # fmt: skip
)


def build_deploy_data(rescuer: str, safe: str) -> bytes:
    return ETH_RESCUE_CREATION_BYTECODE + abi_encode(
        ["address", "address"], [rescuer, safe]
    )


def encode_rescue_call(prepared: list[PreparedAction]) -> bytes:
    # All actions are optional (required=False): a rescue racing a live attacker
    # must never revert, or the whole Flashbots bundle becomes invalid.
    actions = [
        (False, action["to"], action["gas"], bytes.fromhex(action["data"][2:]))
        for action in prepared
    ]
    return RESCUE_SELECTOR + abi_encode(["(bool,address,uint256,bytes)[]"], [actions])


def compute_create_address(sender: str, nonce: int) -> str:
    digest = keccak(rlp.encode([to_canonical_address(sender), nonce]))
    return to_checksum_address(digest[-20:])
